/**
 * render/assets.js — glTF/GLB asset service.
 *
 * SPINE VERSION — the integrator wrote this so the game boots with real
 * library art and can be screenshot-verified.
 *
 * OWNERSHIP: the TEC agent owns this file from now on. It MAY extend it, but
 * MUST keep the exported API documented in src/core/CONTRACT.md.
 *
 * All art comes from the user's asset library. The manifest is generated by
 * tools/build_manifest.py and records, per model: file path, licence, source
 * bbox, world footprint, height, uniform scale and ground y-offset.
 *
 * CLONING A RIGGED CHARACTER (verified, not assumed):
 *   The spine's `cloneModel()` used `Object3D.clone(true)`. In three 0.169
 *   `SkinnedMesh.copy()` ends with `this.skeleton = source.skeleton` — the
 *   clone does NOT get its own skeleton, it SHARES the source's. We verified
 *   this against the real `Knight.glb` (41 joints, 76 clips): after
 *   `root.clone(true)` the clone's `skeleton.bones[0]` is still the
 *   ORIGINAL bone object, not the clone's own bone. The clone's own
 *   AnimationMixer therefore animates bones the skin does not read, and every
 *   clone of a character is welded to one shared rig. `SkeletonUtils.clone()`
 *   rebuilds the skeleton against the clone's own bones and rebinds it, which
 *   is what `cloneRigged()` below uses.
 */

import * as THREE from 'three';
import { GLTFLoader } from 'three/examples/jsm/loaders/GLTFLoader.js';
import { clone as cloneSkeleton } from 'three/examples/jsm/utils/SkeletonUtils.js';
import manifest from '../data/manifest.json';

/** @type {Map<string, THREE.Object3D>} */
const modelCache = new Map();
/** @type {Map<string, {model: THREE.Object3D, clips: THREE.AnimationClip[]}>} */
const characterCache = new Map();
/** @type {Map<string, Promise<THREE.Object3D>>} */
const pending = new Map();

let loader = null;
let ready = false;

/**
 * Cache policy. 0 = unlimited (the default, and the historical behaviour:
 * models are cached forever). A positive value turns the model/character
 * caches into an LRU of that size.
 */
let cacheLimit = 0;

function getLoader() {
  if (!loader) {
    loader = new GLTFLoader();
    loader.setCrossOrigin('anonymous');
  }
  return loader;
}

/** Mark a cache entry as most-recently-used (Map preserves insertion order). */
function touch(cache, key) {
  if (!cache.has(key)) return;
  const value = cache.get(key);
  cache.delete(key);
  cache.set(key, value);
}

/**
 * Evict the least-recently-used entries beyond the limit.
 * The evicted model is NOT disposed: placed clones share its geometry and
 * materials, and disposing them would break the city. Dropping the reference
 * is enough — the GPU buffers live as long as the clones do.
 */
function enforceLimit() {
  if (!cacheLimit) return;
  while (modelCache.size > cacheLimit) {
    const oldest = modelCache.keys().next().value;
    modelCache.delete(oldest);
  }
  while (characterCache.size > cacheLimit) {
    const oldest = characterCache.keys().next().value;
    characterCache.delete(oldest);
  }
}

/**
 * Load a single model by manifest key. Returns a CLONE so callers may
 * transform it freely. The original is cached and never handed out.
 *
 * @param {string} key manifest key, e.g. 'building_A'
 * @returns {Promise<THREE.Object3D|null>}
 */
export function loadModel(key) {
  const rec = manifest.models[key];
  if (!rec) return Promise.resolve(null);
  if (modelCache.has(key)) {
    touch(modelCache, key);
    return Promise.resolve(cloneModel(modelCache.get(key)));
  }
  if (pending.has(key)) {
    return pending.get(key).then(() => cloneModel(modelCache.get(key)));
  }
  const p = new Promise((resolve, reject) => {
    getLoader().load(
      rec.file,
      (gltf) => {
        const root = gltf.scene || gltf.scenes[0];
        prepare(root, rec);
        modelCache.set(key, root);
        enforceLimit();
        resolve(root);
      },
      undefined,
      (err) => reject(err),
    );
  });
  pending.set(key, p);
  return p.then(() => cloneModel(modelCache.get(key))).finally(() => pending.delete(key));
}

/**
 * Load a rigged character by manifest key, returning the model plus its
 * animation clips so the caller can build an AnimationMixer.
 *
 * @param {string} key e.g. 'Knight'
 * @returns {Promise<{model: THREE.Object3D, clips: THREE.AnimationClip[]}|null>}
 */
export function loadCharacter(key) {
  const rec = manifest.characters[key];
  if (!rec) return Promise.resolve(null);
  if (characterCache.has(key)) {
    touch(characterCache, key);
    return Promise.resolve(cloneCharacter(characterCache.get(key)));
  }
  return new Promise((resolve, reject) => {
    getLoader().load(
      rec.file,
      (gltf) => {
        const root = gltf.scene || gltf.scenes[0];
        prepare(root, rec);
        const entry = { model: root, clips: gltf.animations || [] };
        characterCache.set(key, entry);
        enforceLimit();
        resolve(cloneCharacter(entry));
      },
      undefined,
      (err) => reject(err),
    );
  });
}

/** Apply the manifest's scale + ground offset to a freshly loaded model. */
function prepare(root, rec) {
  root.scale.setScalar(rec.scale);
  // Sit the model on the ground plane: shift so its lowest point is y = 0.
  root.position.y = rec.yOffset || 0;
  root.traverse((o) => {
    if (o.isMesh) {
      o.castShadow = true;
      o.receiveShadow = true;
      o.frustumCulled = true;
    }
  });
  root.userData.manifest = rec;
}

/** True when the object contains a skinned mesh. */
function isRigged(obj) {
  let rigged = false;
  obj?.traverse?.((o) => { if (o.isSkinnedMesh) rigged = true; });
  return rigged;
}

/**
 * Clone a rigged model, rebuilding the skeleton against the clone's own
 * bones. Falls back to handing out the ORIGINAL if the skeleton cannot be
 * rebuilt safely — a rigged model must never be duplicated without a valid
 * binding.
 */
function cloneRigged(src) {
  try {
    const c = cloneSkeleton(src);
    let ok = true;
    c.traverse((o) => {
      if (!o.isSkinnedMesh) return;
      if (!o.skeleton || !o.skeleton.bones || o.skeleton.bones.length === 0) ok = false;
      else if (o.skeleton.bones.some((b) => !b)) ok = false;
    });
    if (ok) return c;
  } catch {
    /* fall through to the safe fallback */
  }
  return src;
}

/** Deep clone that preserves material references (shared for batching). */
function cloneModel(src) {
  if (!src) return null;
  const c = isRigged(src) ? cloneRigged(src) : src.clone(true);
  c.position.copy(src.position);
  c.scale.copy(src.scale);
  c.quaternion.copy(src.quaternion);
  c.traverse((o) => { if (o.isMesh) { o.castShadow = true; o.receiveShadow = true; } });
  return c;
}

function cloneCharacter(entry) {
  if (!entry) return null;
  return { model: cloneModel(entry.model), clips: entry.clips.map((c) => c.clone()) };
}

/**
 * Preload a set of models. Returns a progress callback value 0..1.
 * @param {string[]} keys
 * @param {(loaded:number,total:number,key:string)=>void} [onProgress]
 */
export async function preload(keys, onProgress) {
  const total = keys.length || 1;
  let loaded = 0;
  const failures = [];
  await Promise.all(keys.map(async (k) => {
    try {
      await loadModel(k);
    } catch (err) {
      failures.push({ key: k, error: String(err) });
    } finally {
      loaded += 1;
      onProgress?.(loaded, total, k);
    }
  }));
  ready = modelCache.size > 0;
  return { loaded, total, failures };
}

/**
 * Load a set of models with a failure list.
 *
 * @param {string[]} keys
 * @param {(loaded:number,total:number,key:string)=>void} [onProgress]
 * @returns {Promise<{loaded:number,total:number,failures:{key:string,error:string}[]}>}
 */
export async function loadModelSet(keys, onProgress) {
  const list = Array.isArray(keys) ? keys : [];
  const total = list.length || 1;
  let loaded = 0;
  const failures = [];
  await Promise.all(list.map(async (k) => {
    try {
      await loadModel(k);
    } catch (err) {
      failures.push({ key: k, error: String(err) });
    } finally {
      loaded += 1;
      onProgress?.(loaded, total, k);
    }
  }));
  ready = modelCache.size > 0;
  return { loaded, total, failures };
}

/**
 * Load every model and every character in the manifest (128 + 6), reporting
 * progress and collecting failures. Never rejects: a missing asset is
 * reported, not thrown.
 *
 * @param {(loaded:number,total:number,key:string)=>void} [onProgress]
 * @returns {Promise<{loaded:number,total:number,failures:{key:string,error:string}[]}>}
 */
export async function loadAll(onProgress) {
  const modelKeys = Object.keys(manifest.models);
  const charKeys = Object.keys(manifest.characters);
  const total = modelKeys.length + charKeys.length || 1;
  let loaded = 0;
  const failures = [];

  const jobs = [
    ...modelKeys.map((k) => async () => {
      try { await loadModel(k); } catch (err) { failures.push({ key: k, error: String(err) }); }
    }),
    ...charKeys.map((k) => async () => {
      try { await loadCharacter(k); } catch (err) { failures.push({ key: k, error: String(err) }); }
    }),
  ];

  await Promise.all(jobs.map(async (job) => {
    await job();
    loaded += 1;
    onProgress?.(loaded, total, null);
  }));

  ready = modelCache.size > 0;
  return { loaded: loaded - failures.length, total, failures };
}

/**
 * Preload the six characters.
 * @param {(loaded:number,total:number,key:string)=>void} [onProgress]
 * @returns {Promise<{loaded:number,total:number,failures:{key:string,error:string}[]}>}
 */
export async function preloadCharacters(onProgress) {
  const keys = Object.keys(manifest.characters);
  const total = keys.length || 1;
  let loaded = 0;
  const failures = [];
  await Promise.all(keys.map(async (k) => {
    try {
      await loadCharacter(k);
    } catch (err) {
      failures.push({ key: k, error: String(err) });
    } finally {
      loaded += 1;
      onProgress?.(loaded, total, k);
    }
  }));
  ready = modelCache.size > 0;
  return { loaded, total, failures };
}

/** Synchronous access to an already-cached model (clone). */
export function getModel(key) {
  const m = modelCache.get(key);
  if (!m) return null;
  touch(modelCache, key);
  return cloneModel(m);
}

/** Synchronous access to an already-cached character (clone). */
export function getCharacter(key) {
  const c = characterCache.get(key);
  if (!c) return null;
  touch(characterCache, key);
  return cloneCharacter(c);
}

/**
 * The manifest record for a key, whether it is a model or a character.
 * @param {string} key
 * @returns {object|null}
 */
export function getManifestEntry(key) {
  return manifest.models[key] || manifest.characters[key] || null;
}

export function isReady() { return ready; }
export function cachedKeys() { return Array.from(modelCache.keys()); }
export { manifest };

/**
 * Cap the number of cached models / characters. 0 (the default) means
 * unlimited, which is the historical behaviour.
 *
 * @param {number} n
 * @returns {number} the limit now in force
 */
export function setCacheLimit(n) {
  const v = Number(n);
  cacheLimit = Number.isFinite(v) && v > 0 ? Math.floor(v) : 0;
  enforceLimit();
  return cacheLimit;
}

/** @returns {number} the current cache limit (0 = unlimited). */
export function getCacheLimit() {
  return cacheLimit;
}

/**
 * Dispose every cached asset and clear the caches. This is a teardown call:
 * clones already placed in the scene share the cached geometry and materials
 * and must not be alive when this runs.
 */
export function disposeAssets() {
  const disposeTree = (root) => {
    root?.traverse?.((o) => {
      if (!o.isMesh) return;
      o.geometry?.dispose?.();
      const mats = Array.isArray(o.material) ? o.material : [o.material];
      for (const m of mats) {
        if (!m) continue;
        for (const key of Object.keys(m)) {
          const value = m[key];
          if (value && value.isTexture) value.dispose();
        }
        m.dispose?.();
      }
    });
  };
  for (const m of modelCache.values()) disposeTree(m);
  for (const c of characterCache.values()) disposeTree(c.model);
  modelCache.clear();
  characterCache.clear();
  pending.clear();
  ready = false;
}

/** All model keys grouped by family — handy for build menus. */
export function keysByFamily() {
  const out = {};
  for (const [k, v] of Object.entries(manifest.models)) {
    (out[v.family] ||= []).push(k);
  }
  return out;
}
